import { ActionType, EffectHandler } from '@pimpampum/engine';
import { SkillDefinition, action, d, ICON_PREFIX } from '../../players/types.js';

/**
 * Mestre del foc — firebending is breath and drive: quick advances, a fire
 * that grows the longer it burns, and, at the top, the cold-blooded fire. It
 * never steps back, so even its defense hurts.
 */

const FOC_EFFECTS: Record<string, EffectHandler> = {
  // Llamp: lightning needs a calm mind — which is exactly a Focus's rule: if
  // the bender is hurt before it resolves, it never leaves their fingers. When
  // it does, it cannot be guarded and no armour stops it.
  'lightning@cal': {
    getTargetRequirement() { return 'enemy'; },
    onResolve(ctx) {
      const t = ctx.targets[0];
      if (!t || !t.isAlive()) return;
      const dmg = ctx.engine.rollDiceFor(ctx.source, ctx.action.dice, 'attack');
      ctx.engine.log('focus', `⚡ ${ctx.source.name} llança un llamp contra ${t.name}: ${dmg} de dany.`, ctx.source.team);
      ctx.engine.applyPvLoss(t, dmg, ctx.source);
    },
    aiWeight() { return 1.2; },
  },
};

